create or replace function nomologies.hybrid_case_search_v10(query_text text,query_embedding vector default null::vector,filters jsonb default '{}'::jsonb,match_count integer default 30) returns table(case_id uuid,score double precision,exact_identity_score double precision,lexical_score double precision,semantic_score double precision,tag_score double precision,matched_fields text[],title text,short_title text,citation text,case_number text,decision_date date,court text,outcome text,readiness_score integer) language sql stable set search_path=nomologies,public as $$ with params as materialized (select nomologies.normalize_search_text(query_text) nq,regexp_replace(nomologies.normalize_search_text(query_text),'\s+','','g') compact_nq,nomologies.legal_lemma_text(query_text) lemma_q,nomologies.greek_to_latin_search(query_text) latin_q,websearch_to_tsquery('simple',unaccent(coalesce(query_text,''))) exact_tq,nomologies.search_prefix_tsquery(query_text) prefix_tq,nomologies.search_or_prefix_tsquery(query_text) broad_tq,nomologies.search_or_prefix_tsquery(nomologies.legal_lemma_text(query_text)) lemma_tq,trim(coalesce(query_text,''))= '*' browse,greatest(40,least(1200,greatest(1,least(match_count,200))*10)) candidate_limit),synonym_forms as materialized (select distinct nomologies.normalize_search_text(term) form,s.weight::double precision weight from nomologies.legal_search_synonyms s cross join params p cross join lateral unnest(s.terms) term where s.active and exists (select 1 from unnest(s.terms) trigger_term where p.nq like '%' || nomologies.normalize_search_text(trigger_term) || '%' or nomologies.normalize_search_text(trigger_term) like '%' || p.nq || '%' or similarity(nomologies.normalize_search_text(trigger_term),p.nq)>=0.52)),query_forms as materialized (select nq form,1.0::double precision weight from params where nq<> '' union select lemma_q,0.9 from params where lemma_q<> '' union select latin_q,0.75 from params where latin_q<> '' union select form,weight from synonym_forms where form<> ''),query_tokens as materialized (select distinct token,max(weight)::double precision weight from query_forms qf cross join lateral regexp_split_to_table(qf.form,'[^a-z0-9α-ω]+') token where length(token)>=2 and token not in ('και','η','ο','το','τα','τη','την','του','των','σε','στη','στην','στο','στον','με','για','να','που','and','or','not','the','of','to','in','on','for','by','with','from') group by token),current_docs as not materialized (select d.*from nomologies.case_search_documents d join nomologies.cases c on c.id=d.case_id and c.publication_status='published' and c.current_version_id=d.case_version_id where (coalesce(filters->>'caseFamily','')='' or d.case_family=filters->>'caseFamily') and (coalesce(filters->>'legalArea','')='' or d.primary_legal_area=filters->>'legalArea' or d.legal_areas @>array[filters->>'legalArea']) and (coalesce(filters->>'proceedingType','')='' or d.proceeding_type=filters->>'proceedingType') and (coalesce(filters->>'proceduralPosture','')='' or d.procedural_posture=filters->>'proceduralPosture') and (coalesce(filters->>'courtLevel','')='' or d.court_level=filters->>'courtLevel') and (coalesce(filters->>'court','')='' or nomologies.normalize_search_text(d.court) like '%'||nomologies.normalize_search_text(filters->>'court')||'%') and (coalesce(filters->>'outcome','')='' or d.outcome=filters->>'outcome') and (coalesce(filters->>'lawId','')='' or d.law_ids @>array[filters->>'lawId']) and (coalesce(filters->>'yearFrom','')='' or ((filters->>'yearFrom') ~ '^\d{4}$' and d.decision_year>=(filters->>'yearFrom')::integer)) and (coalesce(filters->>'yearTo','')='' or ((filters->>'yearTo') ~ '^\d{4}$' and d.decision_year<=(filters->>'yearTo')::integer)) and (coalesce(filters->>'judge','')='' or exists (select 1 from unnest(d.judges) j where nomologies.normalize_search_text(j) like '%'||nomologies.normalize_search_text(filters->>'judge')||'%'))),exact_identity_raw as materialized (select d.case_id,320::double precision lane_score,array['identity']::text[] matched_fields from current_docs d cross join params p where not p.browse and d.case_number_normalized<>'' and d.case_number_normalized=p.compact_nq union all select d.case_id,310,array['identity'] from current_docs d cross join params p where not p.browse and d.ecli_normalized<>'' and d.ecli_normalized=p.compact_nq union all select d.case_id,300,array['identity'] from current_docs d cross join params p where not p.browse and d.citation_normalized<>'' and d.citation_normalized=p.compact_nq union all select d.case_id,285,array['identity'] from current_docs d cross join params p where not p.browse and d.title_normalized<>'' and d.title_normalized=p.nq),exact_identity as materialized (select case_id,max(lane_score)::double precision lane_score,array['identity']::text[] matched_fields from exact_identity_raw group by case_id),fuzzy_identity as materialized (select d.case_id,greatest(case when d.title_normalized like '%'||p.nq||'%' then 170 else 0 end,case when d.citation_normalized like '%'||p.compact_nq||'%' then 155 else 0 end,case when d.case_number_normalized like '%'||p.compact_nq||'%' then 150 else 0 end,case when d.identity_search_v10 like '%'||p.latin_q||'%' and p.latin_q<>'' then 145 else 0 end,case when d.identity_search_v10 % p.nq then similarity(d.identity_search_v10,p.nq)*135 else 0 end)::double precision lane_score,array['identity']::text[] matched_fields from current_docs d cross join params p where not p.browse and length(p.nq)>=2 and (d.title_normalized like '%'||p.nq||'%' or d.citation_normalized like '%'||p.compact_nq||'%' or d.case_number_normalized like '%'||p.compact_nq||'%' or (p.latin_q<>'' and d.identity_search_v10 like '%'||p.latin_q||'%') or d.identity_search_v10 % p.nq) order by lane_score desc limit (select candidate_limit from params)),identity_fts as materialized (select d.case_id,(ts_rank_cd(d.identity_lexical,p.exact_tq,32)*85+ts_rank_cd(d.identity_lexical,p.prefix_tq,32)*55+ts_rank_cd(d.identity_lemma_lexical,p.lemma_tq,32)*65)::double precision lane_score,array['identity']::text[] matched_fields from current_docs d cross join params p where not p.browse and (d.identity_lexical@@p.exact_tq or d.identity_lexical@@p.prefix_tq or d.identity_lemma_lexical@@p.lemma_tq) order by lane_score desc limit (select candidate_limit from params)),field_precise as materialized (select f.case_id,least(150,sum(f.field_weight*(ts_rank_cd(f.lexical,p.exact_tq,32)*35+ts_rank_cd(f.lexical,p.prefix_tq,32)*25)))::double precision lane_score,array_agg(distinct f.field_name) matched_fields from nomologies.case_search_fields f join current_docs d on d.case_id=f.case_id cross join params p where not p.browse and (f.lexical@@p.exact_tq or f.lexical@@p.prefix_tq) group by f.case_id order by lane_score desc limit (select candidate_limit from params)),field_recall as materialized (select f.case_id,least(105,sum(f.field_weight*(ts_rank_cd(f.lexical,p.broad_tq,32)*16+ts_rank_cd(f.lemma_lexical,p.lemma_tq,32)*22)))::double precision lane_score,array_agg(distinct f.field_name) matched_fields from nomologies.case_search_fields f join current_docs d on d.case_id=f.case_id cross join params p where not p.browse and (f.lexical@@p.broad_tq or f.lemma_lexical@@p.lemma_tq) group by f.case_id order by lane_score desc limit (select candidate_limit from params)),field_trigram as materialized (select f.case_id,least(85,sum(f.field_weight*greatest(case when exists(select 1 from query_forms qf where f.search_v10 like '%'||qf.form||'%') then 5 else 0 end,(select coalesce(max(similarity(f.search_v10,qf.form)*4*qf.weight),0) from query_forms qf))))::double precision lane_score,array_agg(distinct f.field_name) matched_fields from nomologies.case_search_fields f join current_docs d on d.case_id=f.case_id cross join params p where not p.browse and exists(select 1 from query_forms qf where length(qf.form)>=3 and (f.search_v10 like '%'||qf.form||'%' or f.search_v10 % qf.form)) group by f.case_id order by lane_score desc limit (select candidate_limit from params)),tag_candidates as materialized (select cst.case_id,least(100,sum(cst.boost*cst.confidence*qt.weight*case when st.search_v10 like '% '||qt.token||' %' then 12 when st.search_v10 like '%'||qt.token||'%' then 8 else greatest(2,similarity(st.search_v10,qt.token)*7) end))::double precision lane_score,array['concepts']::text[] matched_fields from query_tokens qt join nomologies.smart_tags st on st.search_v10 like '%'||qt.token||'%' or st.search_v10 % qt.token join nomologies.case_smart_tags cst on cst.tag_id=st.id join current_docs d on d.case_id=cst.case_id group by cst.case_id order by lane_score desc limit (select candidate_limit from params)),provision_candidates as materialized (select pl.case_id,least(105,sum(qt.weight*case when nomologies.normalize_search_text(pl.provision_key)=qt.token or nomologies.normalize_search_text(pl.law_id)=qt.token then 25 when pl.search_normalized like '%'||qt.token||'%' then 13 else greatest(2,similarity(pl.search_normalized,qt.token)*10) end))::double precision lane_score,array['provisions']::text[] matched_fields from query_tokens qt join nomologies.provision_links pl on pl.search_normalized like '%'||qt.token||'%' or pl.search_normalized % qt.token join current_docs d on d.case_id=pl.case_id group by pl.case_id order by lane_score desc limit (select candidate_limit from params)),authority_candidates as materialized (select ae.source_case_id case_id,least(95,sum(qt.weight*case when nomologies.normalize_search_text(ae.cited_citation)=qt.token or nomologies.normalize_search_text(ae.cited_ecli)=qt.token then 25 when ae.search_normalized like '%'||qt.token||'%' then 12 else greatest(2,similarity(ae.search_normalized,qt.token)*9) end))::double precision lane_score,array['authorities']::text[] matched_fields from query_tokens qt join nomologies.authority_edges ae on ae.search_normalized like '%'||qt.token||'%' or ae.search_normalized % qt.token join current_docs d on d.case_id=ae.source_case_id group by ae.source_case_id order by lane_score desc limit (select candidate_limit from params)),semantic_nearest as materialized (select f.case_id,f.field_name,greatest(0::double precision,1-(f.embedding<=>query_embedding))::double precision semantic_rank from nomologies.case_search_fields f join current_docs d on d.case_id=f.case_id cross join params p where query_embedding is not null and f.embedding is not null and not p.browse order by f.embedding<=>query_embedding limit (select candidate_limit*5 from params)),semantic_candidates as materialized (select case_id,max(semantic_rank)::double precision lane_score,array_agg(distinct field_name) matched_fields from semantic_nearest where semantic_rank>=0.28 group by case_id),browse_candidates as materialized (select d.case_id,(0.01+d.precedential_score/10000.0)::double precision lane_score,array['filters']::text[] matched_fields from current_docs d cross join params p where p.browse order by d.precedential_score desc,d.decision_date desc nulls last limit (select candidate_limit from params)),lane_rows as materialized (select 'exact_identity' lane,case_id,lane_score,4.0::double precision lane_weight,'exact' grp,matched_fields from exact_identity union all select 'fuzzy_identity',case_id,lane_score,2.4,'lexical',matched_fields from fuzzy_identity union all select 'identity_fts',case_id,lane_score,2.0,'lexical',matched_fields from identity_fts union all select 'field_precise',case_id,lane_score,2.4,'lexical',matched_fields from field_precise union all select 'field_recall',case_id,lane_score,1.5,'lexical',matched_fields from field_recall union all select 'field_trigram',case_id,lane_score,1.1,'lexical',matched_fields from field_trigram union all select 'concepts',case_id,lane_score,1.7,'concept',matched_fields from tag_candidates union all select 'provisions',case_id,lane_score,2.2,'concept',matched_fields from provision_candidates union all select 'authorities',case_id,lane_score,2.0,'concept',matched_fields from authority_candidates union all select 'semantic',case_id,lane_score,1.6,'semantic',matched_fields from semantic_candidates union all select 'browse',case_id,lane_score,1.0,'lexical',matched_fields from browse_candidates),ranked_lanes as materialized (select*,row_number() over(partition by lane order by lane_score desc,case_id) lane_rank from lane_rows where lane_score>0),combined as materialized (select case_id,max(lane_score) filter(where grp='exact')::double precision exact_score,least(170,coalesce(sum(lane_score) filter(where grp='lexical'),0))::double precision lex_score,coalesce(max(lane_score) filter(where grp='semantic'),0)::double precision sem_score,least(120,coalesce(sum(lane_score) filter(where grp='concept'),0))::double precision concept_score,sum(lane_weight/(60.0+lane_rank))::double precision rrf_score from ranked_lanes group by case_id),matched as materialized (select case_id,array_agg(distinct field_name order by field_name) matched_fields from ranked_lanes cross join lateral unnest(matched_fields) field_name group by case_id) select d.case_id,(coalesce(c.exact_score,0)+c.rrf_score*1000+c.sem_score*12+least(100,coalesce(d.precedential_score,0))*0.02)::double precision score,coalesce(c.exact_score,0),c.lex_score,c.sem_score,c.concept_score,m.matched_fields,d.title,d.short_title,d.citation,d.case_number,d.decision_date,d.court,d.outcome,d.readiness_score from combined c join current_docs d on d.case_id=c.case_id join matched m on m.case_id=c.case_id order by score desc,d.precedential_score desc,d.decision_date desc nulls last limit greatest(1,least(match_count,200)); $$;
